import{z as n,x as s,o as B,c as p,q as r,j as i,D as e,d as l,s as A,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"PEB 温度","description":"","frontmatter":{"title":"PEB 温度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/peb-bake.md","filePath":"litho/peb-bake.md","lastUpdated":1791063341000}'),d={name:"litho/peb-bake.md"};function m(P,a,h,D,C,u){const t=s("Mermaid");return B(),p("div",null,[a[2]||(a[2]=r('<h1 id="peb-温度" tabindex="-1">PEB 温度 <a class="header-anchor" href="#peb-温度" aria-label="Permalink to &quot;PEB 温度&quot;">​</a></h1><div class="epigraph"><p>后烘是同一段热过程的两面：温度升高，脱保护跑得快，酸也走得远。轨道烘箱因此是光刻的一部分。</p><footer>—— 据 Mack 对 PEB 作为增益与扩散时钟的讨论，以及 Ito 对催化脱保护的表述整理</footer></div><p><a href="/litho/acid-amplifier">上一课</a>（酸放大器）。把酸的库存写成 PAG 与淬灭剂的当量差。缺口是热时钟：曝光之后、显影之前的后烘（PEB）温度与时间，决定这些酸来得及催化多少次脱保护、以及——下一课才展开的——走多远。本课钉 PEB 温度。酸扩散长度与 LWR 的核，留给<a href="/litho/acid-diffusion-lwr">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAR 在曝光结束时只有酸图，极性大多还没翻。Ito / Willson 的增益发生在 PEB：酸催化保护基脱落，聚合物变碱溶。上一课把阈值钉在「有效酸打过碱」；没有足够的 \\(T\\) 与 \\(t\\)，即使得分够，反应也积不够。缺口因此是烘箱，不是再加一勺 PAG。</p><p>温度差几摄氏度，同一张空中像的 CD 可以走出规格。原因是脱保护速率大致 Arrhenius，对 \\(T\\) 极敏感。产线把 PEB 热板均匀性当成 CDU 的一项，与扫描机剂量环并列——上一课程的剂量闭环管光子，本课的热板管化学时钟。</p><p><span class="marginnote">Arrhenius 规律可以类比成「反应也有体温」：许多化学反应每升 10 °C 速率翻倍甚至更多。热板差两三度不是小数点后的癖好，而相当于把化学时钟拨快或拨慢一大截，CD 跟着走几纳米毫不奇怪。</span></p><h3 id="增益与扩散尚未拆开" tabindex="-1">增益与扩散尚未拆开 <a class="header-anchor" href="#增益与扩散尚未拆开" aria-label="Permalink to &quot;增益与扩散尚未拆开&quot;">​</a></h3><p>同一段热同时加速反应与加速酸的随机行走。本课允许说：升温 → 更敏、轮廓更糊的方向。定量的扩散长度 \\(\\ell\\)、以及它怎样进 LWR，是下一课的符号。不要在这里给「所有 ArF 层 5 nm」这种核。</p><p><span class="marginnote">PEB 延迟（曝光到上热板之间的等待）会让酸挥发、被环境胺额外淬灭，剖面出现 T-top。延迟控制与热板温度是两条规，不要把延迟超差写成「PEB 温度漂移」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>旋钮：热板设定温度、时间、升温斜率、跨片与片内均匀性。表征：固定光学，扫 PEB \\(T\\)，画 CD 与 \\(E_0\\)。斜率 \\(\\mathrm{dCD}/\\mathrm{d}T\\) 是这一层的热敏感度，必须进轨道规格。时间与温度不对易：低温长时间与高温短时间可以凑相近的平均脱保护，却给出不同的扩散核——这正是为什么下一课必须把 \\(\\ell\\) 单独写出，本课禁止用「热剂量」一个数把两面折死。前烘（PAB）改残留溶剂与自由体积，间接改本课的有效速率，但它不是催化时钟；混用两个烘的设定会让故障隔离失败。</p><p><span class="marginnote">把敏感度代成数：若某层 dCD/dT 为每摄氏度 3 nm，片内 ±0.5 °C 的不均匀就贡献 ±1.5 nm 的 CD 摆动，可能吃掉该层套刻预算的三分之一。热板均匀性因此被写进轨道规格，与剂量环并列考核。</span></p><p>控制：热板多区、测温晶圆、忌把第一片与稳态片当同一工作点。PEB 之后才显影；把显影液温度的漂移当成 PEB，会拧错执行器。</p><h3 id="与上一课的联合标定" tabindex="-1">与上一课的联合标定 <a class="header-anchor" href="#与上一课的联合标定" aria-label="Permalink to &quot;与上一课的联合标定&quot;">​</a></h3><p>PAG/淬灭剂比改变化学库存；PEB \\(T\\) 改变库存被用掉的分数和空间铺开。只拧温度来追灵敏度，等于在下一课的模糊核上透支。只加 PAG 不加温，可能 \\(E_0\\) 下来了，暗区泄漏却先到。配方与热板要成套冻结进工艺包。</p>',16)),(B(),i(o,null,{default:e(()=>[A(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACID%5B%22%E6%9C%89%E6%95%88%E9%85%B8%E5%BA%93%E5%AD%98%22%5D%20--%3E%20PEB%5B%22PEB%20%E6%B8%A9%E5%BA%A6%20%2F%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20PEB%20--%3E%20GAIN%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20PEB%20--%3E%20DIFF%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%85%B8%E6%89%A9%E6%95%A3%20%E2%84%93%22%5D%0A%20%20GAIN%20--%3E%20LAT%5B%22%E6%9E%81%E6%80%A7%E6%BD%9C%E5%83%8F%22%5D%0A%20%20PAB%5B%22%E5%89%8D%E7%83%98%20%2F%20%E6%BA%B6%E5%89%82%22%5D%20--%3E%20PEB%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"热板把膜升到设定温度，酸在聚合物自由体积里催化。保护基脱落使极性翻转；正胶曝光区随后可溶。温度高，单位时间内周转次数多，等效灵敏度上升。同时酸的扩散系数上升，边沿的酸更早进入暗区——轮廓外推、NILS 在潜像上下降。这就是「同一旋钮两面」。Mack 把 PEB 既当增益、又当模糊，本课只钉温度是公共执行器。Arrhenius 形式只用来强调对 \\(T\\) 的陡，不在这里标定活化能数字：那随聚合物与酸种类变，抄别人的 eV 会把烘箱规格写错。",-1)),a[5]||(a[5]=E("p",null,"片内热不均匀变成 CD 的慢空间变化（跨场、跨片），看起来像剂量环失锁。要用测温与剂量传感器对拍：热板指纹随热板 ID 走，剂量指纹随扫描方向走。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"193 nm CAR 对 PEB 尤其敏感，几摄氏度是纳米级 CD。不要把 i 线 DNQ 的硬烘经验直接抄成 PEB 规格：那一层化学没有这条催化时钟。")],-1)),(B(),i(o,null,{default:e(()=>[A(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20TUP%5B%22%E7%83%AD%E6%9D%BF%E6%B8%A9%E5%BA%A6%E4%B8%8A%E8%B0%83%E5%87%A0%E5%BA%A6%22%5D%20--%3E%20KA%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E9%80%9F%E7%8E%87%E6%8C%89%E6%8C%87%E6%95%B0%E4%B8%8A%E5%8D%87%22%5D%0A%20%20KA%20--%3E%20SENS%5B%22%E6%9B%B4%E6%95%8F%3A%20%E5%90%8C%E5%89%82%E9%87%8F%E4%B8%8B%E5%8F%8D%E5%BA%94%E6%9B%B4%E5%85%85%E5%88%86%22%5D%0A%20%20TUP%20--%3E%20D%5B%22%E9%85%B8%E7%9A%84%E6%89%A9%E6%95%A3%E7%B3%BB%E6%95%B0%E5%90%8C%E6%AD%A5%E4%B8%8A%E5%8D%87%22%5D%0A%20%20D%20--%3E%20BLUR%5B%22%E6%9B%B4%E7%B3%8A%3A%20%E8%BE%B9%E6%B2%BF%E9%85%B8%E6%9B%B4%E6%97%A9%E8%BF%9B%E5%85%A5%E6%9A%97%E5%8C%BA%2C%20%E8%BD%AE%E5%BB%93%E5%A4%96%E6%8E%A8%22%5D%0A%20%20SENS%20--%3E%20TWO%5B%22%E5%90%8C%E4%B8%80%E6%97%8B%E9%92%AE%E7%9A%84%E4%B8%A4%E4%B8%AA%E8%AF%BB%E5%87%BA%22%5D%0A%20%20BLUR%20--%3E%20TWO%0A%20%20TWO%20--%3E%20SPEC%5B%22dCD%2FdT%20%E5%BF%85%E9%A1%BB%E8%BF%9B%E8%BD%A8%E9%81%93%E8%A7%84%E6%A0%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写扩散方程，不报 LWR 功率谱，不把某胶数据表的 110 °C / 60 s 写成宇宙常数。EUV 金属氧化物的后烘不一定是酸催化，后课换胶时要重声明。显影衬度 \\(\\gamma\\) 是再后面的课：PEB 先把潜像准备好，\\(\\gamma\\) 再切。</p><p>轨道缺陷、烘箱气流，属于设备卫生，不改 Arrhenius 的定义。下一课默认本课的 \\(T\\) 已经是一个被控制的数，再把它翻译成 \\(\\ell\\)。</p><p>片内热指纹与扫描剂量指纹要对拍隔离：前者跟热板 ID 走，后者沿扫描方向。不要用剂量环去补烘箱。</p><p><span class="marginnote">初学者容易把 PEB 延迟超差误诊成「温度漂了」，用升温去补——T-top 没治好，扩散模糊先恶化。延迟管的是酸在等待期被挥发与胺中和，温度管的是反应时钟；各有各的执行器，故障隔离必须分开拧。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEB 温度与时间是 CAR 的催化时钟，也是扩散的公共旋钮。</li><li>\\(\\mathrm{dCD}/\\mathrm{d}T\\) 必须进轨道规格，与扫描机剂量环分开隔离。</li><li>前烘改溶剂，PEB 改催化；PEB 延迟是第三条规。</li><li>低温长时与高温短时平均脱保护可近、扩散核不同。</li><li>扩散长度与 LWR 核是下一课，本课不给纳米常数。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Ito 对化学放大后烘催化的讨论。</li></ul>',7))])}const b=n(d,[["render",m]]);export{f as __pageData,b as default};
